`timescale 1ns / 1ps

// Self-checking testbench for dot_int4_tile (128-lane).
// Test vectors generated by tools/llmsim/gen_vectors.py — golden model.
module tb;
    localparam LANES     = 128;
    localparam TILE_O    = 32;
    localparam LANES_PER_O = LANES / TILE_O;
    localparam ACC_WIDTH = 32;
    localparam AW = LANES_PER_O * 8;   // 32
    localparam WW = LANES * 4;         // 512
    localparam OW = TILE_O * ACC_WIDTH; // 1024

    `include "tb/vectors.svh"

    logic clk, rst_n;
    integer failures, passes, vec_idx, cyc;

    always #5 clk = ~clk;

    logic                       in_valid;
    logic [AW-1:0]              in_a_data;
    logic [WW-1:0]              in_w_data;
    logic                       in_last;
    logic                       in_ready;

    logic                       out_valid;
    logic [OW-1:0]              out_data;
    logic                       out_ready;

    dot_int4_tile #(
        .LANES(LANES), .TILE_O(TILE_O), .ACC_WIDTH(ACC_WIDTH)
    ) dut (
        .clk, .rst_n,
        .in_valid, .in_a_data, .in_w_data, .in_last, .in_ready,
        .out_valid, .out_data, .out_ready
    );

    function logic signed [ACC_WIDTH-1:0] out_ch;
        input integer ch;
        begin
            out_ch = $signed(out_data[ch * ACC_WIDTH +: ACC_WIDTH]);
        end
    endfunction

    task wait_ready;
    begin
        while (!in_ready) @(posedge clk);
    end
    endtask

    task wait_valid;
    begin
        while (!out_valid) @(posedge clk);
    end
    endtask

    task run_vector;
        input integer idx;
        integer tk, nc, c;
        logic [AW-1:0] a_vec [0:999];
        logic [WW-1:0] w_vec [0:999];
        logic [OW-1:0] expected;
        logic fail_flag;
        begin
            tk = TILE_K[idx];
            nc = N_CYCLES[idx];

            // Unpack generated vectors into per-cycle arrays
            case (idx)
                `VEC_UNPACK
            endcase

            wait_ready();
            fail_flag = 0;

            for (c = 0; c < nc; c++) begin
                in_a_data <= a_vec[c];
                in_w_data <= w_vec[c];
                in_valid  <= 1;
                in_last   <= (c == nc - 1);
                @(posedge clk);
            end
            in_valid  <= 0;
            out_ready <= 1;

            wait_valid();

            // Check each output channel
            for (int o = 0; o < TILE_O; o++) begin
                logic signed [ACC_WIDTH-1:0] got = out_ch(o);
                logic signed [ACC_WIDTH-1:0] exp = $signed(expected[o * ACC_WIDTH +: ACC_WIDTH]);
                if (got !== exp) begin
                    if (!fail_flag) begin
                        $display("FAIL vector[%0d] %s (tile_k=%0d)", idx,
                                 `VEC_NAME(idx), tk);
                        fail_flag = 1;
                    end
                    $display("  ch[%0d]: got %0d, exp %0d", o, got, exp);
                    failures = failures + 1;
                end else begin
                    passes = passes + 1;
                end
            end

            @(posedge clk);
            out_ready <= 0;
        end
    endtask

    initial begin : test_main
        $dumpfile("build/sim.vcd");
        $dumpvars(0, tb);
        clk = 0; rst_n = 0; in_valid = 0; out_ready = 0;
        failures = 0; passes = 0;
        #40; rst_n = 1; #10;

        for (vec_idx = 0; vec_idx < N_VECTORS; vec_idx++) begin
            run_vector(vec_idx);
        end

        if (failures == 0)
            $display("\nALL PASS (%0d vectors, %0d channel checks)", N_VECTORS, passes);
        else
            $display("\nFAIL: %0d failures out of %0d checks", failures, passes);
        $finish;
    end

endmodule
